        wxWindow* banner = classic->banner();
        wxSizer*  sizer  = m_notebook->GetContainingSizer();
        const auto index_of = [sizer](wxWindow* window) {
            int index = 0;
            for (wxSizerItem* item : sizer->GetChildren()) {
                if (item->GetWindow() == window)
                    return index;
                ++index;
            }

